            result = {
                "count": count,
                "min_elapsed_ms": min(elapsed_values),
                "max_elapsed_ms": max(elapsed_values),
                # 平均值不取整，以 JSON 数字原样输出
                "avg_elapsed_ms": sum(elapsed_values) / count,
            }
        else:
            result = {
                "count": 0,
                "min_elapsed_ms": None,
                "max_elapsed_ms": None,
                "avg_elapsed_ms": None,
            }
    elif status_summary:
        result = {
            "count": len(rows),
            "success_count": sum(
                1 for row in rows if row[4] == STATUS_SUCCESS
            ),
            "failure_count": sum(
                1 for row in rows if row[4] == STATUS_FAILURE
            ),
        }
    else:
        result = [
            {
                "id": row[0],
                "url": row[1],
                "checked_at": row[2],
                "elapsed_ms": row[3],
                "status": row[4],
                "http_status": row[5],
                "reason": row[6],
            }
            for row in rows
        ]
    print(json.dumps(result, separators=(",", ":"), ensure_ascii=False))
    return 0


